import unittest

from textutils import slugify


class TestSlugifyRegression(unittest.TestCase):
    def test_regression_collapse_separators(self):
        self.assertEqual(slugify("Hello,  World!"), "hello-world")

    def test_regression_strip_edge_separators(self):
        self.assertEqual(slugify("--Hello World--"), "hello-world")
        self.assertEqual(slugify("  ...Hello...  "), "hello")

    def test_regression_only_separators(self):
        self.assertEqual(slugify("!!!"), "")
        self.assertEqual(slugify(""), "")

    def test_regression_keeps_digits(self):
        self.assertEqual(slugify("Top 10 Tips"), "top-10-tips")


if __name__ == "__main__":
    unittest.main()

